() => {
  const buttons = [...document.querySelectorAll('button[draggable="true"]')];
  const src = buttons.find(b => b.title && b.title.startsWith('JGMC'));
  if (!src) return 'src not found';
  const zoneP = [...document.querySelectorAll('p')].find(p => p.textContent.includes('筛选条件 (WHERE'));
  if (!zoneP) return 'zone label not found';
  const zone = [...zoneP.parentElement.children].find(el => el.className && el.className.includes('border-dashed'));
  if (!zone) return 'zone not found';
  const dt = new DataTransfer();
  dt.setData('text/plain', 'JGMC');
  src.dispatchEvent(new DragEvent('dragstart', {bubbles: true, dataTransfer: dt}));
  zone.dispatchEvent(new DragEvent('dragover', {bubbles: true, cancelable: true, dataTransfer: dt}));
  zone.dispatchEvent(new DragEvent('drop', {bubbles: true, cancelable: true, dataTransfer: dt}));
  src.dispatchEvent(new DragEvent('dragend', {bubbles: true}));
  return 'done';
}

() => {
  const h = [...document.querySelectorAll('h3')].find(x => x.textContent.includes('灵活查询验证报表'));
  if (!h) return 'not found';
  h.scrollIntoView({block: 'center'});
  return 'scrolled';
}

() => {
  const btns = [...document.querySelectorAll('button')].filter(b => b.textContent.trim() === '载入');
  if (btns.length === 0) return 'not found';
  btns[0].scrollIntoView({block: 'center'});
  return 'scrolled: ' + btns.length;
}
